// ── Componentes reutilizables ────────────────────────────────────────────────
// El SLA lleva SIEMPRE su aclaración a la vista: "Vencido hace 3 d" sin
// contexto lleva a conclusiones que el SLA no soporta. Es el punto que más
// se malinterpreta en una auditoría.
function SlaCountdown({dueAt,paused,severity}){
 const[t,setT]=useState(0);
 useEffect(()=>{const tick=()=>setT(Date.now());tick();const i=setInterval(tick,60000);return()=>clearInterval(i);},[]);
 if(!dueAt)return <span className="muted small">Sin plazo</span>;
 if(paused)return <span className="badge neutral" title="SLA en pausa con motivo y aprobador. El hallazgo sigue abierto.">En pausa</span>;
 const left=new Date(dueAt).getTime()-t,over=left<0,hours=Math.round(Math.abs(left)/36e5);
 const txt=hours<48?`${hours} h`:`${Math.round(hours/24)} d`;
 return <span className={'sla '+(over?'overdue':'ok')} title={`SLA interno de Gen-Auditor para severidad ${severity||'sin clasificar'}. No es un plazo legal ni de reporte de incidentes.`}>{over?`Vencido hace ${txt}`:`Quedan ${txt}`}</span>;
}

// 64 hexadecimales enteros en una tabla son ruido, no información: se muestran
// truncados y se copian completos.
function HashProof({value,label}){
 const[open,setOpen]=useState(false),[copied,setCopied]=useState(false);
 if(!value)return null;
 const copy=async()=>{try{await navigator.clipboard.writeText(value);setCopied(true);setTimeout(()=>setCopied(false),1800);}catch{setOpen(true);}};
 return <div className="hash-proof">
  {label&&<span className="eyebrow">{label}</span>}
  <button className="mono hash-value" onClick={()=>setOpen(o=>!o)} title={open?'Ocultar':'Ver hash completo'} aria-expanded={open}>{open?value:`${value.slice(0,14)}…${value.slice(-6)}`}</button>
  <button className="icon-btn" onClick={copy} aria-label="Copiar hash completo">{copied?<Check size={14}/>:<Copy size={14}/>}</button>
 </div>;
}

// Mapeo severidad→color en un solo sitio, para que "crítico" no sea rojo en
