function Modal({title,fields,onSave,onClose}){const [busy,setBusy]=useState(false),[error,setError]=useState('');return <div className="modal-scrim" onClick={onClose}><section className="modal" role="dialog" aria-modal="true" aria-label={title} onClick={e=>e.stopPropagation()}><div className="section-head"><h2>{title}</h2><button className="icon-btn" aria-label="Cerrar" onClick={onClose}><X size={20}/></button></div><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await onSave(Object.fromEntries(new FormData(e.currentTarget)));onClose();}catch(err){setError(err.message);}finally{setBusy(false);}}}>{fields.map(f=><label className="field" key={f.name}>{f.label}{f.options?<select name={f.name} required>{f.options.map(x=><option key={x.value} value={x.value}>{x.label}</option>)}</select>:f.type==='textarea'?<textarea name={f.name} required minLength={f.min||3} maxLength={f.max||4000} rows={4}/>:<input autoFocus={f===fields[0]} name={f.name} type={f.type||'text'} required minLength={f.min||2} maxLength={f.max||160} placeholder={f.placeholder||''}/>}</label>)}{error&&<p className="error" role="alert">{error}</p>}<div className="modal-footer"><button type="button" className="btn secondary" onClick={onClose}>Cancelar</button><button className="btn primary" disabled={busy}>{busy?'Guardando…':'Guardar registro'}</button></div></form></section></div>}
