 useEffect(()=>{fetch('/api/public-config').then(x=>x.ok?x.json():Promise.reject()).then(c=>{setConfig(c);setAuth(createClient(c.supabaseUrl,c.publishableKey,{auth:{persistSession:false,autoRefreshToken:true,detectSessionInUrl:false}}));}).catch(()=>setConfig({unavailable:true}));},[]);
