 async function login(e){e.preventDefault();setLoginError('');if(!auth){setLoginError('Configura Supabase en el servidor para iniciar sesión.');return;}const data=new FormData(e.currentTarget);const {data:result,error}=await auth.auth.signInWithPassword({email:data.get('email'),password:data.get('password')});if(error){setLoginError('No fue posible iniciar sesión.');return;}if(config.requireMfa&&result.session){const {data:factorData}=await auth.auth.mfa.listFactors();const factor=factorData?.totp?.find(f=>f.status==='verified');if(!factor){setLoginError('Tu cuenta necesita un factor TOTP ya inscrito por el procedimiento de incorporación.');await auth.auth.signOut();return;}setMfa(factor);return;}setSession(result.session);}
