 function addConsent(){if(!clients.length){setToast('Registra primero un cliente.');return;}newForm('Registrar evidencia de consentimiento',[{name:'client_id',label:'Producto',options:clientOptions},{name:'identity',label:'Identificador del titular · cifrado',max:100},{name:'purpose',label:'Finalidad específica',max:500},{name:'legal_version',label:'Versión del texto legal'},{name:'legal_text',label:'Texto exacto aceptado · registro manual del operador',type:'textarea',min:20,max:15000}],'/consents');}
 if(!session&&!demo)return <div className="login-shell"><div className="login-story"><Logo/><div><span className="eyebrow">EVIDENCIA QUE GENERA CONFIANZA</span><h1>Tu gobernanza.<br/>En un solo lugar.</h1><p>Conecta privacidad, postura de seguridad y trazabilidad para tomar decisiones con evidencia.</p><div className="login-pills"><span><ShieldCheck size={16}/> Seguridad por diseño</span><span><Fingerprint size={16}/> Privacidad primero</span></div></div><small>Gen-Auditor · Una solución de Hefesto Studio</small></div><main className="login-form"><span className="eyebrow">ESPACIO DE TRABAJO SEGURO</span><h2>{mfa?'Verifica tu identidad':'Bienvenido de nuevo'}</h2><p>{mfa?'Ingresa el código de tu aplicación autenticadora.':'Accede a la plataforma de gobernanza y cumplimiento.'}</p><form onSubmit={mfa?verifyMfa:login}>{mfa?<label className="field">Código TOTP<input name="code" inputMode="numeric" pattern="[0-9]{6}" required autoComplete="one-time-code"/></label>:<><label className="field">Correo corporativo<input name="email" type="email" required autoComplete="username" placeholder="nombre@empresa.cl"/></label><label className="field">Contraseña<input name="password" type="password" required autoComplete="current-password"/></label></>}{loginError&&<p className="error" role="alert">{loginError}</p>}<button className="btn primary wide">{mfa?'Verificar y entrar':'Iniciar sesión'}<ArrowRight size={17}/></button></form><div className="divider">o explora la interfaz</div><button className="btn secondary wide" onClick={demoStart}><Eye size={17}/> Abrir demostración</button><p className="small muted">La demostración usa datos ficticios. No realiza escaneos ni registra solicitudes reales.</p></main></div>;
 const nav=[['dashboard','Gobernanza',LayoutDashboard],['privacy','Protección de datos',Fingerprint],['assets','Activos',Boxes],['security','Seguridad externa',Radar],['reports','Reportes',FileCheck2],['audit','Bitácora de auditoría',ScrollText],['settings','Integración ARCOP',Settings]];
 const currentTitle=nav.find(x=>x[0]===view)?.[1];
 const filteredAssets=assets.filter(a=>(!filters.client||a.client_id===filters.client)&&(!filters.kind||a.kind===filters.kind)&&(!filters.criticality||a.criticality===filters.criticality)&&(!filters.exposure||a.exposure===filters.exposure))
  .sort((a,b)=>(b.open_findings-a.open_findings)||(['critical','high','medium','low'].indexOf(a.criticality)-['critical','high','medium','low'].indexOf(b.criticality))||a.name.localeCompare(b.name));
 const REMEDIATION_TABS=[['surface','Superficie externa'],['assets','Activos'],['findings','Hallazgos'],['remediation','Remediación']];
